+
+      .field-label {
+        display: block;
+        font-size: 1rem;
+        font-weight: 700;
+        margin-bottom: 14px;
+      }
+
+      .options {
+        display: grid;
+        gap: 12px;
+      }
+
+      .option {
+        display: flex;
+        align-items: center;
+        gap: 12px;
+        padding: 14px 16px;
+        border-radius: 16px;
+        border: 1px solid rgba(148, 163, 184, 0.24);
+        background: #fff;
+        cursor: pointer;
+        transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
+      }
+
+      .option:hover {
+        border-color: rgba(79, 70, 229, 0.36);
+        box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
+        transform: translateY(-1px);
+      }
+
+      .option input {
+        width: 18px;
+        height: 18px;
+        accent-color: var(--accent);
+        margin: 0;
+      }
+
+      .option span {
+        font-size: 1rem;
+        font-weight: 500;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+        margin-top: 20px;
+      }
+
+      .submit-btn {
+        border: 0;
+        border-radius: 999px;
+        padding: 14px 22px;
+        font-size: 0.98rem;
+        font-weight: 700;
+        color: #fff;
+        background: linear-gradient(135deg, #6366f1, #4f46e5);
+        box-shadow: 0 16px 30px rgba(79, 70, 229, 0.28);
+        cursor: pointer;
+        transition: transform 160ms ease, box-shadow 160ms ease;
+      }
+
+      .submit-btn:hover {
+        transform: translateY(-1px);
+        box-shadow: 0 20px 36px rgba(79, 70, 229, 0.34);
+      }
+
+      .submit-btn:focus-visible,
+      .option:focus-within {
+        outline: 3px solid rgba(79, 70, 229, 0.24);
+        outline-offset: 2px;
+      }
+
+      .status {
+        margin-top: 16px;
+        min-height: 1.5em;
+        color: var(--accent);
+        font-weight: 600;
+      }
+    </style>
+  </head>
+  <body>
+    <div id="root" class="app-shell"></div>
+
+    <script>
+      const root = document.getElementById("root");
+
+      function RadioOption({ name, value, label, checked }) {
+        const wrapper = document.createElement("label");
+        wrapper.className = "option";
+
+        const input = document.createElement("input");
+        input.type = "radio";
+        input.name = name;
+        input.value = value;
+        input.checked = checked;
+        input.required = true;
+
+        const text = document.createElement("span");
+        text.textContent = label;
+
+        wrapper.append(input, text);
+        return wrapper;
+      }
+
+      function NotificationPreferenceForm() {
+        const card = document.createElement("section");
+        card.className = "card";
+
+        const eyebrow = document.createElement("p");
+        eyebrow.className = "eyebrow";
+        eyebrow.textContent = "Preferences";
+
+        const heading = document.createElement("h1");
+        heading.textContent = "Notification settings";
+
+        const subtitle = document.createElement("p");
+        subtitle.className = "subtitle";
+        subtitle.textContent = "Choose one way we can reach you with important updates.";
+
+        const form = document.createElement("form");
+        form.noValidate = true;
+
+        const field = document.createElement("div");
+        field.className = "form-field";
+
+        const label = document.createElement("label");
+        label.className = "field-label";
+        label.setAttribute("for", "notification-email");
+        label.textContent = "How do you prefer to receive notifications?";
+
+        const options = document.createElement("div");
+        options.className = "options";
+        options.setAttribute("role", "radiogroup");
+        options.setAttribute("aria-labelledby", "notification-preference-label");
+
+        label.id = "notification-preference-label";
+
+        options.append(
+          RadioOption({ name: "notification-preference", value: "email", label: "Email", checked: true }),
+          RadioOption({ name: "notification-preference", value: "sms", label: "SMS" }),
+          RadioOption({ name: "notification-preference", value: "push", label: "Push Notifications" })
+        );
+
+        field.append(label, options);
+
+        const actions = document.createElement("div");
+        actions.className = "actions";
+
+        const button = document.createElement("button");
+        button.className = "submit-btn";
+        button.type = "submit";
+        button.textContent = "Submit";
+
+        const status = document.createElement("p");
+        status.className = "status";
+        status.setAttribute("aria-live", "polite");
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+          const selected = form.querySelector('input[name="notification-preference"]:checked');
+          status.textContent = selected ? `Saved preference: ${selected.value}` : "Please choose a preference.";
+        });
+
+        actions.append(button);
+        form.append(field, actions, status);
+        card.append(eyebrow, heading, subtitle, form);
+        return card;
+      }
+
+      function App() {
+        const app = document.createElement("main");
+        app.append(NotificationPreferenceForm());
+        return app;
+      }
+
+      root.append(App());
+    </script>
+  </body>
+</html>
*** End Patch
